const Prefixed = (Base) =>
  class extends Base {
    label() { return `new ${super.label()}`; }
  };

const Short = (Base) =>
  class extends Base {
    label() { return super.label().slice(0, 5); }
  };

class Item {
  label() { return "notebook"; }
}

class A extends Prefixed(Short(Item)) {}
class B extends Short(Prefixed(Item)) {}

console.log(new A().label());
console.log(new B().label());
console.log(new B() instanceof Item);
